"""ANSI rendering helpers for jd style diffs."""
import difflib
import json

RED = "\x1b[31m"
GREEN = "\x1b[32m"
RESET = "\x1b[0m"


def _word_line(line: str, other: str, color: str) -> str:
    """Color only changed characters between JSON value strings."""
    prefix = line[:2]
    try:
        value = json.loads(line[2:])
        peer = json.loads(other[2:])
    except Exception:
        return color + line + "\n" + RESET
    if not isinstance(value, str) or not isinstance(peer, str):
        return color + line + "\n" + RESET
    seq = difflib.SequenceMatcher(a=value, b=peer, autojunk=False)
    chunks = []
    for op, a1, a2, b1, b2 in seq.get_opcodes():
        part = value[a1:a2]
        if op == "equal":
            chunks.append(json.dumps(part, ensure_ascii=False)[1:-1])
        elif part:
            chunks.append(color + json.dumps(part, ensure_ascii=False)[1:-1] + RESET)
    return prefix + '"' + "".join(chunks) + '"\n'


def colorize(rendered: str, words: bool = False) -> str:
    """Apply jd ANSI conventions to an uncolored jd diff."""
    lines = rendered.splitlines(keepends=True)
    result = []
    additions = [i for i, ln in enumerate(lines) if ln.startswith("+ ")]
    removals = [i for i, ln in enumerate(lines) if ln.startswith("- ")]
    paired = {}
    if words:
        for ri, ai in zip(removals, additions):
            paired[ri] = ai
    for i, line in enumerate(lines):
        if line.startswith("^ ") and line.rstrip("\n") in ('^ "COLOR"', '^ "COLOR_WORDS"'):
            continue
        if line.startswith("- "):
            if words and i in paired:
                result.append(_word_line(line.rstrip("\n"), lines[paired[i]].rstrip("\n"), RED))
            else:
                result.append(RED + line + RESET)
        elif line.startswith("+ "):
            if words and i in paired.values():
                ri = next(k for k, v in paired.items() if v == i)
                result.append(_word_line(line.rstrip("\n"), lines[ri].rstrip("\n"), GREEN))
            else:
                result.append(GREEN + line + RESET)
        else:
            result.append(line)
    marker = '^ "COLOR_WORDS"\n' if words else '^ "COLOR"\n'
    pos = 0
    while pos < len(result) and result[pos].startswith("^ "):
        pos += 1
    result.insert(pos, marker)
    return "".join(result)

"""Small JSON Patch and Merge Patch helpers used by the jd CLI clone."""
import copy


def _tokens(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("invalid JSON pointer")
    return [part.replace("~1", "/").replace("~0", "~") for part in pointer[1:].split("/")]


def _index(token, length, allow_end=False):
    if token == "-" and allow_end:
        return length
    if not token.isdigit() or (len(token) > 1 and token[0] == "0"):
        raise ValueError("invalid array index")
    idx = int(token)
    if idx < 0 or idx > length or (idx == length and not allow_end):
        raise ValueError("array index out of bounds")
    return idx


def _parent(doc, tokens, create=False):
    cur = doc
    for token in tokens[:-1]:
        if isinstance(cur, dict):
            if token not in cur:
                raise ValueError("path does not exist")
            cur = cur[token]
        elif isinstance(cur, list):
            i = _index(token, len(cur))
            cur = cur[i]
        else:
            raise ValueError("path does not exist")
    return cur, tokens[-1] if tokens else None


def get(doc, pointer):
    cur = doc
    for token in _tokens(pointer):
        if isinstance(cur, dict):
            cur = cur[token]
        elif isinstance(cur, list):
            cur = cur[_index(token, len(cur))]
        else:
            raise ValueError("path does not exist")
    return cur


def _set(doc, pointer, value, add=False, remove=False):
    tokens = _tokens(pointer)
    if not tokens:
        if remove:
            raise ValueError("cannot remove document root")
        return copy.deepcopy(value)
    parent, key = _parent(doc, tokens)
    if isinstance(parent, dict):
        if remove and key not in parent:
            raise ValueError("path does not exist")
        if not add and not remove and key not in parent:
            raise ValueError("path does not exist")
        if remove:
            del parent[key]
        else:
            parent[key] = copy.deepcopy(value)
    elif isinstance(parent, list):
        i = _index(key, len(parent), allow_end=add)
        if remove:
            parent.pop(i)
        elif add:
            parent.insert(i, copy.deepcopy(value))
        else:
            parent[i] = copy.deepcopy(value)
    else:
        raise ValueError("path does not exist")
    return doc


def apply_json_patch(document, operations):
    """Apply a sequence of RFC 6902 operations, returning a fresh document."""
    result = copy.deepcopy(document)
    for op in operations:
        kind, path = op.get("op"), op.get("path")
        if not isinstance(path, str):
            raise ValueError("operation path must be a string")
        if kind == "test":
            if get(result, path) != op.get("value"):
                raise ValueError("test operation failed")
        elif kind == "remove":
            result = _set(result, path, None, remove=True)
        elif kind == "add":
            result = _set(result, path, op.get("value"), add=True)
        elif kind == "replace":
            result = _set(result, path, op.get("value"))
        elif kind in ("copy", "move"):
            source = op.get("from")
            if not isinstance(source, str):
                raise ValueError("operation from must be a string")
            value = copy.deepcopy(get(result, source))
            if kind == "move":
                result = _set(result, source, None, remove=True)
            result = _set(result, path, value, add=True)
        else:
            raise ValueError("unsupported operation")
    return result


def apply_merge_patch(target, patch):
    """Apply RFC 7386 merge patch."""
    if not isinstance(patch, dict):
        return copy.deepcopy(patch)
    if not isinstance(target, dict):
        target = {}
    else:
        target = copy.deepcopy(target)
    for key, value in patch.items():
        if value is None:
            target.pop(key, None)
        else:
            target[key] = apply_merge_patch(target.get(key), value)
    return target

