    if source_format == "patch" and target_format == "jd":
        return _patch_to_jd(source)
    if source_format == "merge" and target_format == "jd":
        return _merge_to_jd(json.loads(source))
    if source_format in ("json", "yaml") and target_format in ("json", "yaml"):
        if source_format == "json":
            value = json.loads(source)
        else:
