            value = loads(source)
        if target_format == "json":
            return _compact(value)
        try:
            from yamlutil import dumps
            return dumps(value)
        except ImportError:
            return _json_to_yaml(value)
    raise ValueError("unsupported translation: " + _compact(formats))

